export function createAwardsJourney(parent){
const awards=[
{title:'KIST SciTech Fair',date:'JANUARY 2025',scope:'National · Team award',result:'Winner',asset:'kist',alt:'Prasiddha holding his KIST SciTech Fair trophy and wearing a medal'},
{title:'FusionHacks 2',date:'AUGUST 2025',scope:'International · Team award',result:'Winner',asset:'fusionhacks',alt:'NATERIDA robotics project with FusionHacks 2 winner recognition',url:'https://fusionhacks-2.devpost.com/project-gallery'},
{title:'FounderForge',date:'DECEMBER 2025',scope:'International · Team award',result:'Winner',asset:'founderforge',alt:'FounderForge competition page showing winner recognition',url:'https://founderforge1.devpost.com/project-gallery'},
{title:'SET Exhibition',date:'FEBRUARY 2026',scope:'National · Team award',result:'Winner',asset:'set',alt:'Prasiddha beside the robotics project, trophy, and certificate at SET Exhibition'},
{title:'International Olympiad in AI',date:'AUGUST 2026 · ASTANA',scope:'International · Individual distinction',result:'Honorable Mention',asset:'ioai',alt:'Prasiddha holding the Nepal flag at IOAI Astana 2026'}];
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*x*(x*(x*6-15)+10)};
const el=document.createElement('section');el.className='awards-film';el.setAttribute('aria-label','Awards and recognition');el.innerHTML=`<canvas aria-hidden="true"></canvas><div class="awards-horizon"></div><div class="awards-intro"><p class="eyebrow">09 / MOMENTS THAT MATTER</p><h2>Some moments<br><em>stay with you.</em></h2><p>From building together to representing Nepal.</p></div><div class="awards-gallery">${awards.map((a,i)=>`<figure class="award-frame" data-award="${i}"><div class="award-float"><div class="award-photo"><img src="assets/award-${a.asset}.png" alt="${a.alt}" loading="eager" decoding="async"><div class="award-glint"></div></div><figcaption>${a.date}</figcaption></div></figure>`).join('')}</div><div class="award-copy"><p class="eyebrow award-counter"></p><p class="award-result"></p><h2></h2><p class="award-meta"></p><a class="award-proof" target="_blank" rel="noopener">View competition results ↗</a><p class="award-finale">A moment for Nepal.<br><em>A reason to keep going.</em></p></div><nav class="award-nav" aria-label="Award chapters"><button class="award-prev" aria-label="Previous award">←</button>${awards.map((a,i)=>`<button data-jump="${i}" aria-label="${a.title}" title="${a.title}"><span>0${i+1}</span><i></i></button>`).join('')}<button class="award-next" aria-label="Next award">→</button></nav><button class="award-back">← Back to experience</button>`;parent.append(el);
const q=s=>el.querySelector(s),frames=[...el.querySelectorAll('.award-frame')],ctx=q('canvas').getContext('2d');let t=0,paused=false,visible=false,last=0,time=0,active=-1,position=0;
function jump(value){const p=document.querySelector('#projects'),start=p.offsetTop+(p.offsetHeight-innerHeight)*.9;scrollTo({top:start+(value-1.5)*innerHeight,behavior:paused?'instant':'smooth'})}
function go(i){jump(42+Math.max(0,Math.min(4,i))*2.3+.65)}el.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>go(Number(b.dataset.jump)));q('.award-prev').onclick=()=>go(active-1);q('.award-next').onclick=()=>go(active+1);q('.award-back').onclick=()=>jump(38.6);
function draw(ms){requestAnimationFrame(draw);const dt=Math.min(.04,(ms-last)/1000);last=ms;if(!visible||!ctx||document.hidden||parent.classList.contains('world-ready'))return;if(!paused)time+=dt;const c=ctx.canvas,w=c.clientWidth,h=c.clientHeight,d=Math.min(devicePixelRatio,2);if(c.width!==Math.round(w*d)||c.height!==Math.round(h*d)){c.width=Math.round(w*d);c.height=Math.round(h*d)}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const cx=w*.5,cy=h*.48,f=Math.min(w,h)*.8,project=(x,y,z)=>({x:cx+x*f/z,y:cy+y*f/z});
ctx.save();ctx.globalCompositeOperation='screen';
// A moving floor and light shafts establish depth behind the photographic gallery.
for(let j=0;j<22;j++){const z=1+((j*1.2-position*3-(paused?0:time*.11))%26+26)%26,a=project(-10,2.7,z),b=project(10,2.7,z);ctx.strokeStyle='#a6c7b11a';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
for(let j=-6;j<=6;j++){const a=project(j,2.7,1),b=project(j,2.7,30);ctx.strokeStyle='#b2bfa116';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
for(let k=0;k<3;k++){const x=w*(.2+k*.3)+Math.sin(time*.22+k)*w*.07,g=ctx.createLinearGradient(x,0,x+w*.15,h);g.addColorStop(0,'#f3d8a62b');g.addColorStop(.6,'#ddc49109');g.addColorStop(1,'#ddc49100');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x-12,0);ctx.lineTo(x+12,0);ctx.lineTo(x+w*.27,h);ctx.lineTo(x-w*.22,h);ctx.closePath();ctx.fill()}
for(let j=0;j<130;j++){const z=1+((j*.317-position*2-(paused?0:time*.14))%24+24)%24,a=j*2.399,p=project(Math.cos(a)*5,Math.sin(a)*2.7,z);ctx.globalAlpha=Math.min(.7,2/z);ctx.fillStyle=j%5?'#9dc4ca':'#f3d495';ctx.beginPath();ctx.arc(p.x,p.y,Math.max(.6,2.7/z),0,Math.PI*2);ctx.fill()}ctx.restore();
}requestAnimationFrame(draw);
return {update(value,stop){t=value;paused=stop;visible=t>39.4;el.inert=!visible;el.style.visibility=visible?'visible':'hidden';el.style.opacity=ease((t-39.4)/1.1);el.classList.toggle('motion-paused',paused);const intro=1-ease((t-41.1)/.85),gallery=ease((t-41.6)/.8),p=clamp((t-42)/(2.3*4))*4,index=Math.min(4,Math.floor(p)),local=p-index;position=index+(index<4?ease((local-.6)/.4):0);q('.awards-intro').style.opacity=intro;q('.awards-gallery').style.opacity=gallery;const chosen=Math.min(4,Math.round(position)),delta=Math.abs(position-chosen),copyOpacity=gallery*(1-ease(delta/.45));q('.award-copy').style.opacity=copyOpacity;q('.award-copy').inert=copyOpacity<.5;q('.award-copy').style.transform=paused?'none':`translateY(${delta*25}px)`;q('.award-nav').style.opacity=gallery;q('.award-nav').inert=gallery<.9;
frames.forEach((frame,i)=>{const distance=i-position,focus=1-clamp(Math.abs(distance)),x=distance*(innerWidth<760?110:86),z=-Math.abs(distance)*650;frame.style.opacity=gallery*(Math.abs(distance)>1.4?0:Math.max(.08,1-Math.abs(distance)*.8));frame.style.transform=paused?`translateX(${distance*110}vw)`:`translate3d(${x}vw,${Math.abs(distance)*-25}px,${z}px) rotateY(${-distance*34}deg)`;frame.style.filter=`brightness(${.45+focus*.55})`;frame.style.zIndex=String(10-Math.round(Math.abs(distance)*3));frame.setAttribute('aria-hidden',String(i!==chosen));});
if(chosen!==active){active=chosen;const a=awards[active];q('.award-counter').textContent=`0${active+1} / 05 · ${a.date}`;q('.award-result').textContent=a.result;q('.award-copy h2').textContent=a.title;q('.award-meta').textContent=a.scope;q('.award-proof').hidden=!a.url;if(a.url)q('.award-proof').href=a.url;q('.award-finale').hidden=active!==4;q('.award-prev').disabled=active===0;q('.award-next').disabled=active===4;el.querySelectorAll('[data-jump]').forEach((b,i)=>b.setAttribute('aria-current',String(i===active)));}
}};
}
